import re

def parse_retry_after(value: object) -> int | None:
    if not isinstance(value, str):
        return None

    # Match unsigned ASCII decimal seconds with optional surrounding whitespace
    # and leading zeros.
    # The regex ensures only digits are present in the core of the string.
    match = re.fullmatch(r"\s*[0-9]+\s*", value)
    if not match:
        return None

    try:
        val = int(match.group(0).strip())
        if 0 <= val <= 86400:
            return val
    except ValueError:
        pass

    return None
